create table ai_quiz_gen_log (num_of_questions integer not null, created_at timestamp(6), gen_log_id bigint generated by default as identity, quiz_id bigint not null, ai_model varchar(255), difficulty varchar(255), prompt_text varchar(255), topic varchar(255), primary key (gen_log_id));
create table answer_option (is_correct boolean not null, opt_id bigint generated by default as identity, question_id bigint not null, opt_text varchar(255), primary key (opt_id));
create table answer_submission (is_correct boolean not null, id bigint generated by default as identity, question_id bigint not null, response_timems bigint, submitted_at timestamp(6), participant_id varchar(255) not null, room_id varchar(255) not null, selected_answer varchar(255), primary key (id), unique (room_id, question_id, participant_id));
create table quiz (time_duration integer not null, total_questions integer not null, creation_time timestamp(6), quiz_id bigint generated by default as identity, created_by varchar(255) not null, quiz_description varchar(255), quiz_difficulty varchar(255), quiz_title varchar(255), status varchar(255), primary key (quiz_id));
create table quiz_attempt (score float(53), status smallint check (status between 0 and 2), attempt_id bigint generated by default as identity, quiz_id bigint not null, started_at timestamp(6), submitted_at timestamp(6), room_id varchar(255) not null, user_id varchar(255) not null, primary key (attempt_id), unique (user_id, room_id));
create table quiz_participants (id bigint generated by default as identity, joined_at timestamp(6), participant_id varchar(255) not null, room_id varchar(255) not null, primary key (id), unique (participant_id, room_id));
create table quiz_questions (question_id bigint generated by default as identity, quiz_id bigint not null, answer_explanation varchar(255), correct_answer varchar(255), question_text varchar(255), question_type varchar(255), primary key (question_id));
create table quiz_room (created_at timestamp(6), quiz_id bigint not null, room_code varchar(255), room_host varchar(255) not null, room_id varchar(255) not null, room_status varchar(255), primary key (room_id), unique (room_code));
create table scores (rank integer not null, total_score float(53) not null, id bigint generated by default as identity, participant_id varchar(255) not null, room_id varchar(255) not null, primary key (id), unique (room_id, participant_id));
create table users (user_email varchar(255) not null unique, user_id varchar(255) not null, user_name varchar(255), user_password varchar(255) not null, user_role varchar(255) not null check (user_role in ('USER','ADMIN','CREATOR')), primary key (user_id));
alter table if exists ai_quiz_gen_log add constraint fkey_quiz_tbl foreign key (quiz_id) references quiz;
alter table if exists answer_option add constraint fkey_quiz_question_tbl foreign key (question_id) references quiz_questions;
alter table if exists answer_submission add constraint quiz_participants_fkey foreign key (participant_id) references users;
alter table if exists answer_submission add constraint fkey_quiz_question_tbl foreign key (question_id) references quiz_questions;
alter table if exists answer_submission add constraint fkey_quiz_room_tbl foreign key (room_id) references quiz_room;
