alter table if exists quiz_attempt add constraint fkey_quiz_tbl foreign key (quiz_id) references quiz;
alter table if exists quiz_attempt add constraint fkey_quiz_room_tbl foreign key (room_id) references quiz_room;
alter table if exists quiz_attempt add constraint quiz_attempt_fkey foreign key (user_id) references users;
